sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_b2 as B2  # noqa: E402
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

OUT = "data/p1v4/runs/api"
SMOKE = "data/p1v4/runs/api_smoke"
# Drift check (pre-freeze scoring review item 3), run just before the test: the chosen setting re-asked on a fixed dev
# sample (seed 11, about 300 questions; not the smoke sample); the share of decisions that flip at the frozen
# thresholds must stay within the limit (repeat calls on 2026-11-16: B2-strong 0 of 35 flips, B3 2 of 35).
DRIFT = "data/p1v4/runs/api_drift"
DRIFT_POINTS, DRIFT_SEED = 250, 11
DRIFT_LIMITS = {"b2strong": 0.02, "b2fast": 0.03, "b3": 0.08, "b2ideal": 0.02}
B2_EXAMPLES = "data/p1v4/runs/b2local/examples.json"
MODELS = {"b2fast": "gemini-4-hydrogen", "b2strong": "gemini-4-carbon", "b3": "gemini-4-carbon",
          "b2ideal": "gemini-4-carbon"}
# USD per 1M tokens, Standard tier, until 2026-11-30 (aistudio.google.com/docs/pricing, read 2026-11-16); implicit
# caching only; thinking billed as output. Carbon doubles from 2026-12-01.
PRICES = {"gemini-4-hydrogen": {"in": 1.50, "cached": 0.075, "out": 7.50},
          "gemini-4-carbon": {"in": 2.00, "cached": 0.10, "out": 10.00}}
B3_EXAMPLES = (0, 1, 5, 9, 11, 16)    # of the 48: r_hear 1, r_hear 2, s_react 1, s_move 1, s_move 3, episode return
B3_NOTE = ("You can also hear the audio of each case. For a single moment it is the last 8 seconds before the "
           "decision; for a longer session it runs from the start of the session up to the decision, which is at the "
           "end of the audio. The situation text comes from automatic tools (speech recognition, speaker "
           "identification and a sound detector) and can be wrong; use what you hear.")
NOTE_FILES = {"note": ["configs/b2_note_v1.txt"],
              "prec": ["configs/b2_note_v1.txt", "configs/b2_detector_reliability_v1.txt"]}
URL = "https://generativelanguage.googleapis.com/v1beta/models/{}:generateContent"
# MAX_OUT 2048 cut 6 of 140 thinking answers in the smoke run (thoughts 2,045 tokens, no answer), so 8192 from the
# full run on (2026-11-16). Flex (half price, same model, variable latency, 429/503 when busy: retry with backoff,
# client timeout >= 10 min) is used for the full dev run after a check that it gives the Standard tier's answers.
TOP, MAX_OUT, TRIES, TIMEOUT_S = 20, 8192, 12, 900
WORDS = {"S": ("STOP", "CONTINUE"), "R": ("RESPOND", "NOT")}           # (yes word, no word)
ANSWER_RX = {q: re.compile(r"\b(" + "|".join(w) + r")\b", re.I) for q, w in WORDS.items()}


# ------------------------------------------------------------------------------------------------ prompts

def parse_setting(system, setting):
    m = re.fullmatch(r"([KA])(\d+)_(think|nothink)(?:_(note|prec))?", setting)
    if not m:
        raise SystemExit(f"bad setting {setting}")
    kind, n, think, variant = m.group(1), int(m.group(2)), m.group(3), m.group(4)
    if system == "b3" and not (kind == "A" and n in (0, 6) and variant in (None, "prec")):
        raise SystemExit("b3 settings: A0 or A6, optionally _prec (reliability table, amendment 2.6)")
    if system != "b3" and not (kind == "K" and n in (6, 24, 48)):
        raise SystemExit("b2 settings: K6, K24 or K48")
    if system == "b2ideal" and variant:
        raise SystemExit("b2ideal: no note variants (perception is perfect)")
    return n, think, variant


def examples_48():
    """The 48 B2 examples as (row, k), in B2-local's order; checked against B2.pick_examples(48)."""
    ids = json.load(open(B2_EXAMPLES, encoding="utf-8"))["examples"]
    picked = [f"{r['unit']}|{r['version']}|{k}" for r, k in B2.pick_examples(48)]
    assert ids == picked, "examples.json differs from pick_examples(48)"
    rows = {(r["unit"], r["version"]): r for r in D.folder_rows(os.path.join(D.RENDER, "train_d00"))}
    return [(rows[tuple(e.split("|")[:2])], int(e.split("|")[2])) for e in ids]


def situation(ctx, r, k, ideal):
    return ctx.ideal_situation(r, k) if ideal else ctx.situation(r, k, "full")


def example_text(ctx, r, k, ideal):
    text, asks = situation(ctx, r, k, ideal)
    return f"{B2.case_block(text, asks)}\nAnswers: {B2.answer_words(r['points'][k]['gold'], asks)}"


def wav_b64(r, k):
    """The audio B3 hears at point k: the 8 s window, or an episode from its start to the decision point."""
    p = r["points"][k]
    if r["part"] == "episode":
        x, sr = sf.read(r["full"], dtype="int16")
        x = x[:int(round(p["t"] * sr))]
    else:
        x, sr = sf.read(p["window"], dtype="int16")
    assert sr == 16000
    buf = io.BytesIO()
    sf.write(buf, x, sr, format="WAV", subtype="PCM_16")
    return base64.b64encode(buf.getvalue()).decode("ascii")


class Prompts:
    def __init__(self, system, n, split="dev", variant=None):
        self.system, self.n = system, n
        self.ideal = system == "b2ideal"
        if system == "b3":       # B3 has its own note; "_prec" adds only the reliability table (amendment 2.6)
            self.extra = (open(NOTE_FILES["prec"][-1], encoding="utf-8").read().strip() if variant == "prec"
                          else None)
        else:
            self.extra = ("\n\n".join(open(p, encoding="utf-8").read().strip() for p in NOTE_FILES[variant])
                          if variant else None)
        self.ctx = C.Context(split, asr="turbo")       # test/replication open only after the freeze (p1v4_data)
        ex_ctx = C.Context(None, folders=["train_d00"], asr="turbo")
        ex = examples_48()
        if system == "b3":
            self.examples = [(wav_b64(r, k), example_text(ex_ctx, r, k, False))
                             for r, k in (ex[i] for i in B3_EXAMPLES[:n])]
        else:
            self.block = "\n\n".join(example_text(ex_ctx, r, k, self.ideal) for r, k in ex[:n])

    def case(self, r, k):
        text, asks = situation(self.ctx, r, k, self.ideal)
        return B2.case_block(text, asks), [a[0] for a in asks]

    def parts(self, r, k, case, q):
        if self.system != "b3":
            if self.extra is None:
                return [{"text": B2.prompt(case, self.block) + "\n" + B2.QUESTION[q]}]
            return [{"text": f"{B2.POLICY}\n\n{self.extra}\n\nExamples:\n\n{self.block}\n\nNow decide this case.\n"
                             f"{case}\n{B2.QUESTION[q]}"}]
        note = B3_NOTE if self.extra is None else f"{B3_NOTE}\n\n{self.extra}"
        parts = [{"text": f"{B2.POLICY}\n\n{note}" + ("\n\nExamples:" if self.examples else "")}]
        for i, (audio, text) in enumerate(self.examples):
            parts += [{"text": f"\n\nExample {i + 1}. Audio:"},
                      {"inlineData": {"mimeType": "audio/wav", "data": audio}}, {"text": "\n" + text}]
        parts += [{"text": "\n\nNow decide this case. Audio:"},
                  {"inlineData": {"mimeType": "audio/wav", "data": wav_b64(r, k)}},
                  {"text": f"\n{case}\n{B2.QUESTION[q]}"}]
        return parts


# ------------------------------------------------------------------------------------------------ calls

def read_key(path):
    data = json.loads(open(path, encoding="utf-8").read())
    return next(str(data[n]).strip() for n in ("GEMINI_API_KEY", "GOOGLE_API_KEY") if data.get(n))


def call(key, model, parts, think, tier="standard", logprobs=True):
    """logprobs=False: answers only (freeze amendment 2.2-2.4; the API refuses logprob requests since 2026-11-19)."""
    cfg = {"temperature": 0, "maxOutputTokens": MAX_OUT}
    if logprobs:
        cfg.update({"responseLogprobs": True, "logprobs": TOP})
    if think == "nothink":
        cfg["thinkingConfig"] = {"thinkingBudget": 0}
    body = {"contents": [{"role": "user", "parts": parts}], "generationConfig": cfg}
    if tier == "flex":
        body["service_tier"] = "flex"
    data = json.dumps(body).encode("utf-8")
    err = None
    for attempt in range(TRIES):
        req = urllib.request.Request(URL.format(model), data=data,
                                     headers={"x-goog-api-key": key, "Content-Type": "application/json",
                                              "X-Server-Timeout": str(TIMEOUT_S - 60)})
        t0 = time.perf_counter()
        try:
            with urllib.request.urlopen(req, timeout=TIMEOUT_S) as resp:
                js = json.loads(resp.read().decode("utf-8"))
                js["_served_tier"] = resp.headers.get("x-gemini-service-tier")
                return 200, js, time.perf_counter() - t0, attempt
        except urllib.error.HTTPError as e:
            err = (e.code, e.read().decode("utf-8", "replace")[:400])
            if e.code not in (429, 500, 502, 503, 504):
                break
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as e:
            err = (-1, repr(e)[:300])
        time.sleep(min(300.0, 2.0 * 2 ** attempt) * (0.5 + random.random()))
    return err[0], {"error": err[1]}, None, attempt


def side(token, q):
    t = re.sub(r"[^A-Za-z]", "", token).upper()
    if len(t) < 2:
        return None
    yes, no = WORDS[q]
    return "yes" if yes.startswith(t) else "no" if no.startswith(t) else None


def parse(js, q):
    """has_logprobs (added 2026-11-21, post-fix review M4): whether the reply carried a logprobs block at all; the
    probability-mode stop (amendment 13.2) uses it, not the scoring path ("answer (no matching token)" also happens,
    rarely, with logprobs present)."""
    cand = (js.get("candidates") or [{}])[0]
    text = "".join(p.get("text", "") for p in cand.get("content", {}).get("parts", []) if not p.get("thought"))
    out = {"text": text[:300], "finish": cand.get("finishReason"), "has_logprobs": bool(cand.get("logprobsResult"))}
    if js.get("promptFeedback", {}).get("blockReason"):
        out["blocked"] = js["promptFeedback"]["blockReason"]
    m = ANSWER_RX[q].search(text)
    if not m:
        out.update(score=0.5, how="no answer word", answer=None)
        return out
    answer = "yes" if m.group(1).upper() == WORDS[q][0] else "no"
    out["answer"] = answer
    lp = cand.get("logprobsResult") or {}
    chosen, tops = lp.get("chosenCandidates", []), lp.get("topCandidates", [])
    i = next((j for j, c in enumerate(chosen) if side(c.get("token", ""), q)), None)
    if i is None or i >= len(tops) or side(chosen[i].get("token", ""), q) != answer:
        out.update(score=1.0 if answer == "yes" else 0.0, how="answer (no matching token)")
        return out
    cands = {c.get("token", ""): c.get("logProbability", -1e9) for c in tops[i].get("candidates", [])}
    cands.setdefault(chosen[i].get("token", ""), chosen[i].get("logProbability", -1e9))
    p = {"yes": 0.0, "no": 0.0}
    for tok, lpv in cands.items():
        s = side(tok, q)
        if s:
            p[s] += math.exp(lpv)
    if p["yes"] + p["no"] <= 0:
        out.update(score=1.0 if answer == "yes" else 0.0, how="answer (no candidates)")
    else:
        out.update(score=p["yes"] / (p["yes"] + p["no"]), how="logprobs", mass=p["yes"] + p["no"], step=i)
    return out


def cost_of(model, usage, tier="standard"):
    pr = PRICES[model]
    prompt = usage.get("promptTokenCount", 0)
    cached = usage.get("cachedContentTokenCount", 0)
    out = usage.get("candidatesTokenCount", 0) + usage.get("thoughtsTokenCount", 0)
    usd = ((prompt - cached) * pr["in"] + cached * pr["cached"] + out * pr["out"]) / 1e6
    return usd / 2 if tier == "flex" else usd           # Flex: half the Standard prices (pricing page)


# ------------------------------------------------------------------------------------------------ run

def dev_points(sample=None, split="dev", seed=0):
    rows = D.load_rows(split)
    pts = [(r, p["k"]) for r in rows for p in r["points"]]
    if sample:
        rng = random.Random(seed)
        by = {}
        for r, k in pts:
            by.setdefault(r["part"], []).append((r, k))
        per = math.ceil(sample / len(by))
        pts = [x for part in sorted(by) for x in rng.sample(by[part], min(per, len(by[part])))]
    return rows, pts


def run_dir(system, setting, split="dev", sample=None, tier="standard", drift=False, answers=False, final=False,
            drift_tag=None, root=None):
    """answers=True (added 2026-11-20): answers-only runs go to their own folder ("<setting>_answers"), so a split
    never mixes the two scorings and a switch to answers re-asks everything (freeze amendment 2.3).
    Added 2026-11-21 (amendment 13.2): final=True puts a split's final run under data/p1v4/runs/final/<split>/api/
    for every split (the dev rehearsal never writes into the stored dev folders); a drift run gets its own dated
    folder (drift_tag); root: an explicit parent folder (the re-choice after a failed drift check)."""
    leaf = f"{setting}_answers" if answers else setting
    if root:
        return os.path.join(root, system, leaf)
    if drift:
        return os.path.join(DRIFT, system, leaf if drift_tag is None else f"{leaf}@{drift_tag}")
    if final:
        return os.path.join(f"data/p1v4/runs/final/{split}/api", system, leaf)
    if sample:
        return os.path.join(SMOKE if tier == "standard" else f"{SMOKE}_{tier}", system, leaf)
    return os.path.join(OUT if split == "dev" else f"data/p1v4/runs/final/{split}/api", system, leaf)


def run(system, setting, key_path, sample=None, workers=16, max_usd=200.0, tier="standard", split="dev",
        drift=False, answers=False, final=False, drift_tag=None, root=None):
    """split: dev, or test/replication in the final run (open only after the freeze). drift: re-ask the fixed dev
    sample of the drift check (see drift()). answers: requests without logprobs, scored by the answer word.
    Returns {"dir", "expected", "already", "answered", "errors", "usd", "stopped", "stop_kind"} (added 2026-11-21):
    expected = every question of the points (answered before or not); stop_kind "budget", "errors" or
    "no_logprobs" (a probability-mode answer scored without logprobs: amendment 13.2, the run stops at once)."""
    n, think, variant = parse_setting(system, setting)
    model = MODELS[system]
    out_dir = run_dir(system, setting, split, sample, tier, drift, answers, final, drift_tag, root)
    if drift and drift_tag is not None and os.path.isdir(out_dir) and os.listdir(out_dir):
        raise SystemExit(f"{out_dir} is not empty: a drift run always starts in a new folder (amendment 13.2)")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "responses.jsonl")
    done = set()
    if os.path.exists(path):
        for line in open(path, encoding="utf-8"):
            rec = json.loads(line)
            if rec["status"] == 200:
                done.add((rec["id"], rec["q"]))
    _, pts = dev_points(DRIFT_POINTS, "dev", DRIFT_SEED) if drift else dev_points(sample, split)
    pr = Prompts(system, n, "dev" if drift else split, variant)
    items, expected = [], 0
    for r, k in pts:
        case, qs = pr.case(r, k)
        pid = f"{r['unit']}|{r['version']}|{k}"
        for q in qs:
            expected += 1
            if (pid, q) not in done:
                items.append((pid, r, k, case, q))
    already = expected - len(items)
    key = read_key(key_path)
    print(f"{system} {setting} ({model}, {think}, {tier} tier): {len(items)} questions to ask, {len(done)} already "
          f"answered; {workers} workers, stop above ${max_usd:.0f}", flush=True)

    def work(it):
        pid, r, k, case, q = it
        st, js, dt, attempts = call(key, model, pr.parts(r, k, case, q), think, tier, logprobs=not answers)
        rec = {"id": pid, "q": q, "status": st, "latency_s": dt, "retries": attempts, "tier": tier,
               "mode": "answers" if answers else "probabilities", "time": time.strftime("%Y-%m-%d %H:%M:%S")}
        if st == 200:
            rec.update(parse(js, q))
            rec["usage"] = {k2: v for k2, v in js.get("usageMetadata", {}).items() if isinstance(v, int)}
            rec["model_version"] = js.get("modelVersion")
            rec["served_tier"] = js.get("_served_tier")
            rec["usd"] = cost_of(model, rec["usage"], tier)
        else:
            rec["error"] = js.get("error")
        return rec

    spent, n_ok, n_err, hows, t0, stop, stop_kind = 0.0, 0, 0, {}, time.time(), None, None
    prompt_tok, cached_tok = 0, 0
    with open(path, "a", encoding="utf-8") as f, cf.ThreadPoolExecutor(workers) as ex:
        futs = [ex.submit(work, it) for it in items]
        try:
            for j, fu in enumerate(cf.as_completed(futs), 1):
                if fu.cancelled():
                    continue
                rec = fu.result()                    # calls already running when a stop is called are still kept
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")
                f.flush()
                if rec["status"] == 200:
                    n_ok += 1
                    spent += rec["usd"]
                    hows[rec["how"]] = hows.get(rec["how"], 0) + 1
                    prompt_tok += rec["usage"].get("promptTokenCount", 0)
                    cached_tok += rec["usage"].get("cachedContentTokenCount", 0)
                else:
                    n_err += 1
                    if n_err <= 5:
                        print(f"error {rec['status']}: {str(rec.get('error'))[:200]}", flush=True)
                if j % 100 == 0 or j == len(futs):
                    el = time.time() - t0
                    print(f"{j}/{len(futs)} done ({n_err} errors), ${spent:.2f}, cached "
                          f"{cached_tok / max(1, prompt_tok):.0%} of prompt tokens, {el / 60:.1f} min, "
                          f"eta {el / j * (len(futs) - j) / 60:.0f} min, {hows}", flush=True)
                no_lp = (not answers and rec["status"] == 200 and rec.get("has_logprobs") is False
                         and rec.get("answer") is not None)  # review M4; fix check M1: replies with no answer word
                #   (thinking that used the whole output budget) score 0.5 either way and do not show a lost logprobs
                if stop is None and (no_lp or spent > max_usd or (j >= 50 and n_err > 0.2 * j)):
                    if no_lp:            # amendment 13.2: logprobs gone in a probability-mode run -> stop at once
                        stop_kind = "no_logprobs"
                        stop = f"{rec['id']} {rec['q']} was scored without logprobs ({rec['how']})"
                    elif spent > max_usd:
                        stop_kind, stop = "budget", f"spent ${spent:.2f} (limit ${max_usd:.0f})"
                    else:
                        stop_kind, stop = "errors", f"{n_err} errors in {j} calls"
                    print("STOPPING:", stop, flush=True)
                    for x in futs:
                        x.cancel()
        except KeyboardInterrupt:
            for x in futs:
                x.cancel()
            raise
    print(f"{'stopped' if stop else 'finished'} {system} {setting}: {n_ok} answered, {n_err} errors, "
          f"${spent:.2f}", flush=True)
    return {"dir": out_dir, "expected": expected, "already": already, "answered": n_ok, "errors": n_err,
            "usd": spent, "stopped": stop is not None, "stop_kind": stop_kind, "stop": stop}


# ------------------------------------------------------------------------------------------------ choose, cost

def load_scores(path):
    best = {}
    for line in open(path, encoding="utf-8"):
        rec = json.loads(line)
        if rec["status"] == 200:
            best[(rec["id"], rec["q"])] = rec
    return best


def choose(system):
    rows = D.load_rows("dev")
    pr_ctx = C.Context("dev", asr="turbo")
    asked = [(f"{r['unit']}|{r['version']}|{p['k']}", a[0]) for r in rows for p in r["points"]
             for a in pr_ctx.situation(r, p["k"], "full")[1]]
    log, best = [], None
    for d in sorted(glob.glob(os.path.join(OUT, system, "*", "responses.jsonl"))):
        setting = os.path.basename(os.path.dirname(d))
        got = load_scores(d)
        missing = [x for x in asked if x not in got]
        if len(missing) > 0.005 * len(asked):
            print(f"{setting}: {len(missing)} of {len(asked)} questions unanswered, skipped", flush=True)
            continue
        sc = {}
        for pid, q in asked:
            sc.setdefault(pid, {})[q] = got[(pid, q)]["score"] if (pid, q) in got else 0.5
        json.dump(sc, open(os.path.join(OUT, system, f"scores_dev_{setting}.json"), "w"))
        keyed = {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v for k, v in sc.items()}
        res = S.operating_point(rows, keyed)
        hows = {}
        for rec in got.values():
            hows[rec["how"]] = hows.get(rec["how"], 0) + 1
        res.update(setting=setting, missing=len(missing), how=hows,
                   usd=sum(r.get("usd", 0) for r in got.values()))
        log.append(res)
        print(json.dumps({k: res[k] for k in ("setting", "th_s", "th_r", "floors_met", "primary", "lowest_floor",
                                              "parts", "missing", "how", "usd")}), flush=True)
        rank = (res["floors_met"], res["primary"], res["lowest_floor"])
        if best is None or rank > best[0]:
            best = (rank, setting)
    json.dump({"log": log, "chosen": best[1] if best else None},
              open(os.path.join(OUT, system, f"{system}_dev.json"), "w"), indent=1)
    print(system, "chosen:", best[1] if best else None)


def sealed_split(split):
    """test, replication and their variant folders (e.g. test_dnoise10): the final run's splits."""
    return not str(split).startswith(("dev", "train"))


def meta_path(score_path):
    return score_path[:-5] + ".meta.json"


def split_scores(system, setting, split, answers=False, final=False, sample=None):
    """The scores of a split's responses at a frozen setting (final run), as choose() does on dev. answers: the
    answers-only folder, written as scores_<split>_<setting>_answers.
    Added 2026-11-21 (amendment 13.1): a sidecar <score file>.meta.json holds the counts (questions, missing, answered
    without an answer word). On test and replication (and their variant folders) no score file is written while a
    question is missing: the final run re-asks until none is (final_run). On dev an unanswered question still scores
    0.5 and is counted. A response with no answer word scores 0.5 everywhere, as registered (plan 6.4).
    final: the final-run folder (data/p1v4/runs/final/<split>/api/); sample: dev rehearsal on a sample of points."""
    rows = D.load_rows(split)
    ctx = C.Context(split, asr="turbo")
    if sample:
        if sealed_split(split):
            raise SystemExit("--sample is for the dev rehearsal only")
        keep = {(r["unit"], r["version"], k) for r, k in dev_points(sample, split)[1]}
        pts = [(r, p) for r in rows for p in r["points"] if (r["unit"], r["version"], p["k"]) in keep]
    else:
        pts = [(r, p) for r in rows for p in r["points"]]
    asked = [(f"{r['unit']}|{r['version']}|{p['k']}", a[0]) for r, p in pts
             for a in ctx.situation(r, p["k"], "full")[1]]
    d = run_dir(system, setting, split, answers=answers, final=final)
    rp = os.path.join(d, "responses.jsonl")
    got = load_scores(rp) if os.path.exists(rp) else {}
    sc, missing, no_word = {}, 0, 0
    for pid, q in asked:
        sc.setdefault(pid, {})[q] = got[(pid, q)]["score"] if (pid, q) in got else 0.5
        missing += (pid, q) not in got
        no_word += (pid, q) in got and got[(pid, q)].get("how") == "no answer word"
    out = os.path.join(os.path.dirname(d), f"scores_{split}_{setting}{'_answers' if answers else ''}.json")
    meta = {"split": split, "system": NAME.get(system, system), "setting": setting,
            "mode": "answers" if answers else "probabilities", "questions": len(asked), "missing": missing,
            "no_answer_word": no_word, "sample": sample, "time": time.strftime("%Y-%m-%d %H:%M:%S")}
    json.dump(meta, open(meta_path(out), "w"), indent=1)
    if missing and sealed_split(split):
        raise SystemExit(f"{system} {setting} on {split}: {missing} of {len(asked)} questions unanswered; no score "
                         f"file written (amendment 13.1: re-ask until none is missing)")
    json.dump(sc, open(out, "w"))
    print(f"{system} {setting} on {split}: {len(asked)} questions, {missing} unanswered (scored 0.5), {no_word} "
          f"without an answer word -> {out}")
    return missing


# ------------------------------------------------------------------------------------------------ final run
# (added 2026-11-20, freeze amendment third draft 2.2-2.6 and 4.2 item 5: the test-day order and contingencies)

NAME = {"b2fast": "B2-fast", "b2strong": "B2-strong", "b3": "B3", "b2ideal": "B2-ideal"}
PROBE_POINT = ("r_hear", 0)          # the first dev R-hear point in load order: a fixed, harmless question


def frozen(split):
    """The frozen settings: the freeze record (hashes checked) for test and replication, the rehearsal record on dev."""
    import p1v4_freeze as FZ
    return json.load(open(FZ.REHEARSAL))["settings"] if split == "dev" else FZ.verify_or_stop()["settings"]


def final_root(split):
    d = f"data/p1v4/runs/final/{split}/api"
    os.makedirs(d, exist_ok=True)
    return d


NO_LOGPROBS = "Logprobs is not enabled"        # the API's 400 message since 2026-11-19 (stored dev responses)


def probe(key_path, split):
    """Step 2 of amendment 2.2: one logprob request per model on a fixed dev question, before the split is opened.
    Writes final/<split>/api/probe.json (status, whether logprobs came back) and modes.json (each rival's mode for
    the whole run). Amendment 13.2 (2026-11-21): a model is set to answers only on the 400 reply whose message is
    "Logprobs is not enabled ..."; probabilities only on a 200 reply that carries logprobs; anything else (rate
    limit, server error, timeout, key, a 200 without logprobs) stops without a modes file. An existing modes.json is
    never overwritten (a deliberate re-probe moves it aside first and says why in the log)."""
    frozen(split)
    d = final_root(split)
    mp = f"{d}/modes.json"
    if os.path.exists(mp):
        raise SystemExit(f"{mp} exists: the probe does not overwrite it (amendment 13.2)")
    key = read_key(key_path)
    rows = [r for r in D.load_rows("dev") if r["part"] == PROBE_POINT[0]]
    r = rows[PROBE_POINT[1]]
    k = r["points"][0]["k"]
    pr = Prompts("b2fast", 6, "dev")
    case, qs = pr.case(r, k)
    res, mode_of_model = {}, {}
    for model in sorted(set(MODELS.values())):
        st, js, dt, _ = call(key, model, pr.parts(r, k, case, qs[0]), "nothink", logprobs=True)
        cand = (js.get("candidates") or [{}])[0] if st == 200 else {}
        err = None if st == 200 else str(js.get("error"))
        res[model] = {"status": st, "logprobs": bool(cand.get("logprobsResult")),
                      "error": None if err is None else err[:300],
                      "model_version": js.get("modelVersion") if st == 200 else None,
                      "time": time.strftime("%Y-%m-%d %H:%M:%S")}
        if st == 200 and res[model]["logprobs"]:
            mode_of_model[model] = "probabilities"
        elif st == 400 and NO_LOGPROBS in (err or ""):
            mode_of_model[model] = "answers"
        else:
            mode_of_model[model] = None
    json.dump({"probe": res, "point": f"{r['unit']}|{r['version']}|{k}"}, open(f"{d}/probe.json", "w"), indent=1)
    bad = sorted(m for m, x in mode_of_model.items() if x is None)
    if bad:
        print(json.dumps({"probe": res}, indent=1))
        raise SystemExit(f"probe failed for {bad} (neither logprobs nor the 'not enabled' refusal): no modes file "
                         f"written; find the cause and probe again (amendment 13.2)")
    modes = {NAME[s]: mode_of_model[MODELS[s]] for s in NAME}
    json.dump(modes, open(mp, "w"), indent=1)
    print(json.dumps({"probe": res, "modes": modes}, indent=1))


def modes_of(split):
    p = f"{final_root(split)}/modes.json"
    if not os.path.exists(p):
        raise SystemExit(f"{p} missing: run `probe` first (amendment 2.2 step 2)")
    return json.load(open(p))


def override_path(system, split):
    return f"{final_root(split)}/override_{system}.json"


def effective(system, split, mode, st=None):
    """The rival's setting for this split and mode (amendment 13.2): the frozen one, or the re-choice written after a
    failed drift check (final/<split>/api/override_<system>.json). Returns the mode entry of the frozen settings plus
    the rival's answer loss and its SE (points), with "override" = the file used or None."""
    st = st or frozen(split)
    a = st["api"][NAME[system]]
    e = dict(a[mode])
    for f in ("answer_loss_points", "answer_loss_se_points", "answer_loss_se_points_5f"):
        e[f] = a.get(f)
    e["override"] = None
    p = override_path(system, split)
    if os.path.exists(p):
        o = json.load(open(p))
        if o["mode"] == mode:
            e.update(setting=o["setting"], th_s=o["th_s"], th_r=o["th_r"], override=p.replace("\\", "/"))
            if mode == "answers":
                e.update(answer_loss_points=o["answer_loss_points"], answer_loss_se_points=o["answer_loss_se_points"],
                         answer_loss_se_points_5f=o["answer_loss_se_points_5f"])
    return e


def checks_today(system, split):
    p = f"{final_root(split)}/drift_checks.jsonl"
    today = time.strftime("%Y-%m-%d")
    if not os.path.exists(p):
        return []
    return [x for x in (json.loads(line) for line in open(p, encoding="utf-8"))
            if x["system"] == NAME[system] and str(x.get("date", x["time"][:10])) == today]


def governing_check(system, split, mode=None):
    """Amendment 13.2 supplement (2026-11-21, post-fix review M5): the first complete drift check of the day governs
    that day for the rival. An incomplete check (fewer questions answered today than the sample) is not valid: it
    neither passes nor fails, and the check is asked again. A complete check is not repeated on the same day.
    mode (fix check M2): only checks in the rival's current mode count, so after a `switch` (amendment 2.3) one check
    in the new mode can be asked the same day."""
    return next((x for x in checks_today(system, split) if x.get("complete") and (mode is None or x["mode"] == mode)),
                None)


def test_answers_exist(system, split, mode=None):
    """Whether the rival already has answers on this split (final run, package API, noise API, plan 7.5 row); mode
    (fix check M2): only folders of that mode count (answers-mode folders end in "_answers"), so the unused
    probability answers before a `switch` do not count as answers in the new mode."""
    pats = ((f"data/p1v4/runs/final/{split}/api/{system}/*/responses.jsonl", 1),
            (f"data/p1v4/runs/grounding/{split}/api/{system}/*/*/responses.jsonl", 2),
            (f"data/p1v4/runs/final/{split}/noise/*/api/{system}/*/responses.jsonl", 1))
    for pat, up in pats:
        for p in glob.glob(pat):
            leaf = p.replace("\\", "/").split("/")[-1 - up]
            if mode is not None and leaf.endswith("_answers") != (mode == "answers"):
                continue
            for line in open(p, encoding="utf-8"):
                if json.loads(line).get("status") == 200:
                    return True
    return False


def ok_today(system, split, st=None):
    """(ok, reason): may the rival's questions on this split be asked today (amendment 13.2 and its supplement)?
    Yes when today's governing check passed in the day's mode at the effective setting (the frozen one, or the
    re-choice), or on the day of a re-choice, which follows today's failed governing check."""
    st = st or frozen(split)
    mode = modes_of(split)[NAME[system]]
    e = effective(system, split, mode, st)
    if e["override"] and json.load(open(e["override"]))["time"][:10] == time.strftime("%Y-%m-%d"):
        return True, "re-chosen today"
    g = governing_check(system, split, mode)
    if g is None:
        return False, "no complete drift check today (run `drift-check`)"
    if g.get("pass") is not True:
        return False, (f"today's governing drift check ({g['time']}) did not pass: "
                       + ("re-choose (`rechoose`)" if not (sealed_split(split) and test_answers_exist(system, split, mode)) else
                          "the rival already has answers on this split, so its remaining runs wait for a day whose "
                          "check passes (amendment 13.2 supplement)"))
    if g["mode"] != mode or g["setting"] != e["setting"]:
        return False, f"today's check was in {g['mode']} at {g['setting']}, the rival runs in {mode} at {e['setting']}"
    return True, "passed"


def final_run(system, key_path, split, workers=16, max_usd=2000.0, sample=None, max_rounds=8):
    """Amendment 2.2 step 6: the rival at its frozen setting in the mode the probe fixed, then its scores.
    Amendment 13 (2026-11-21): needs a passed drift check of the same day for this rival, mode and setting, or a
    re-choice written today after a failed one (then the re-chosen setting runs); the questions are re-asked in whole
    rounds until none is missing (a request that failed its 12 tries is asked again in the next round); the scores
    are written only then. sample: the dev rehearsal of this path on a sample of points (final/dev/api/)."""
    if sample and split != "dev":
        raise SystemExit("--sample is for the dev rehearsal only")
    st = frozen(split)
    mode = modes_of(split)[NAME[system]]
    e = effective(system, split, mode, st)
    answers = mode == "answers"
    ok, why = ok_today(system, split, st)                # amendment 13.2 and its supplement (review M5)
    if not ok:
        raise SystemExit(f"{NAME[system]}: {why}")
    spent, res = 0.0, None
    for rnd in range(1, max_rounds + 1):
        res = run(system, e["setting"], key_path, workers=workers, max_usd=max_usd - spent, split=split,
                  answers=answers, final=True, sample=sample)
        spent += res["usd"]
        missing = res["expected"] - res["already"] - res["answered"]
        print(f"{NAME[system]} round {rnd}: {missing} of {res['expected']} questions missing, ${spent:.2f} so far",
              flush=True)
        if res["stop_kind"] == "no_logprobs":
            raise SystemExit(f"{NAME[system]}: logprobs lost mid-run ({res['stop']}); amendment 2.3: run `switch`, "
                             f"then `final` again (the answers run starts from nothing)")
        if res["stop_kind"] == "budget" or spent >= max_usd:
            raise SystemExit(f"{NAME[system]}: budget ${max_usd:.0f} reached with {missing} questions missing")
        if missing <= 0:
            break
        time.sleep(min(600, 60 * rnd))                    # let a rate-limit burst pass before the next round
    missing = split_scores(system, e["setting"], split, answers, final=True, sample=sample)
    print(f"{NAME[system]} on {split}: mode {mode}, setting {e['setting']}"
          f"{' (re-chosen today: ' + e['override'] + ')' if e['override'] else ''}, {missing} unanswered, "
          f"${spent:.2f}")


def switch_to_answers(system, split):
    """Amendment 2.3, first row: a rival in probability mode that loses logprobs mid-run switches entirely to
    answers; its probability answers are not used. The answers run then starts from nothing (its own folder)."""
    modes = modes_of(split)
    modes[NAME[system]] = "answers"
    json.dump(modes, open(f"{final_root(split)}/modes.json", "w"), indent=1)
    note = {"system": NAME[system], "switched": time.strftime("%Y-%m-%d %H:%M:%S"),
            "reason": "logprobs refused mid-run (amendment 2.3)"}
    with open(f"{final_root(split)}/switches.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps(note) + "\n")
    print(json.dumps(note))


def drift_check(system, key_path, split, workers=16):
    """Amendment 2.2 step 4 (and 2.5 in the rehearsal): the fixed 250-question dev sample re-asked in the mode the
    probe fixed, at the frozen setting; flips at the frozen thresholds against the stored dev answers of the same
    setting; limit from the frozen settings (answers: r + 0.03, r measured in the rehearsal)."""
    st = frozen(split)
    mode = modes_of(split)[NAME[system]] if split != "dev" or os.path.exists(f"{final_root(split)}/modes.json") \
        else "probabilities"
    e = effective(system, split, mode, st)            # review M5: after a re-choice, check the re-chosen setting
    answers = mode == "answers"
    g = governing_check(system, split, mode)
    if g is not None:                                 # amendment 13.2 supplement: the first complete check governs
        raise SystemExit(f"{NAME[system]}: today's complete drift check ({g['time']}, pass {g.get('pass')}) governs "
                         f"the day; it is not repeated (amendment 13.2 supplement)")
    tag = time.strftime("%Y%m%d-%H%M%S")              # amendment 13.2: every check asks again, in a new folder
    rr = run(system, e["setting"], key_path, workers=workers, max_usd=50.0, drift=True, answers=answers,
             drift_tag=tag)
    new = load_scores(os.path.join(rr["dir"], "responses.jsonl"))
    if e["override"]:                                 # the re-choice's own dev answers of that setting are the reference
        o = json.load(open(e["override"]))
        ref = os.path.join(o["root"], system, e["setting"] + ("_answers" if answers else ""), "responses.jsonl")
    else:
        ref = dev_reference(system, e["setting"])
    old = load_scores(ref)
    th = {"S": e["th_s"], "R": e["th_r"]}

    def score(rec):
        return rec["score"] if not answers else (1.0 if rec.get("answer") == "yes" else 0.0
                                                 if rec.get("answer") == "no" else 0.5)
    keys = sorted(k for k in new if k in old)
    flips = sum((score(new[k]) >= th[k[1]]) != (score(old[k]) >= th[k[1]]) for k in keys)
    rate = flips / max(1, len(keys))
    limit = e.get("drift_limit")
    slack = int(0.005 * len(new)) if e["override"] else 0     # a re-choice may lack <= 0.5% of its dev answers
    complete = rr["already"] == 0 and len(new) >= rr["expected"] and len(keys) >= len(new) - slack
    res = {"system": NAME[system], "mode": mode, "setting": e["setting"], "questions": len(keys), "flips": flips,
           "flip_rate": rate, "limit": limit,
           "pass": None if limit is None or not complete else bool(rate <= limit),   # incomplete: not valid (M5)
           "expected": rr["expected"], "asked_today": len(new), "complete": complete,
           "reference": ref.replace("\\", "/"), "override": e["override"],
           "folder": rr["dir"].replace("\\", "/"), "date": time.strftime("%Y-%m-%d"),
           "model_versions": sorted({str(r.get("model_version")) for r in new.values()}),
           "time": time.strftime("%Y-%m-%d %H:%M")}
    if not complete:
        res["invalid_reason"] = (f"{len(new)} of {rr['expected']} questions answered today"
                                 + ("" if len(keys) == len(new) else f"; {len(new) - len(keys)} without a dev reference")
                                 + "; not valid: ask the check again (amendment 13.2 supplement)")
    with open(f"{final_root(split)}/drift_checks.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps(res) + "\n")
    print(json.dumps(res))
    return res


def dev_reference(system, setting):
    """The stored dev responses of a setting: asked with logprobs (<setting>/), or, for a candidate first run without
    them (B3's reliability-table candidate, amendment 2.6), <setting>_answers/."""
    p = os.path.join(OUT, system, setting, "responses.jsonl")
    return p if os.path.exists(p) else os.path.join(OUT, system, f"{setting}_answers", "responses.jsonl")


def answer_drift_rate(system, key_path):
    """Amendment 2.5, measured before the freeze: the answers-only drift rate r of a rival at its answer-mode setting
    (the 250-question sample re-asked without logprobs, decisions against the stored dev answers). Writes r and the
    limit r + 0.03 to results/main_v04/answer_drift_dev.json, which p1v4_freeze.py reads."""
    st = frozen("dev")
    e = st["api"][NAME[system]]["answers"]
    tag = time.strftime("%Y%m%d-%H%M%S")              # amendment 13.2: a new folder for every measurement
    rr = run(system, e["setting"], key_path, max_usd=50.0, drift=True, answers=True, drift_tag=tag)
    new = load_scores(os.path.join(rr["dir"], "responses.jsonl"))
    old = load_scores(dev_reference(system, e["setting"]))
    th = {"S": e["th_s"], "R": e["th_r"]}

    def ans(rec):
        return 1.0 if rec.get("answer") == "yes" else 0.0 if rec.get("answer") == "no" else 0.5
    keys = sorted(k for k in new if k in old)
    if len(new) < rr["expected"] or len(keys) < len(new):
        raise SystemExit(f"{NAME[system]}: {len(new)} of {rr['expected']} answered ({len(keys)} with a dev reference);"
                         f" r not written, measure again")
    r = sum((ans(new[k]) >= th[k[1]]) != (ans(old[k]) >= th[k[1]]) for k in keys) / max(1, len(keys))
    path = "results/main_v04/answer_drift_dev.json"
    cur = json.load(open(path)) if os.path.exists(path) else {}
    cur[NAME[system]] = {"setting": e["setting"], "questions": len(keys), "r": r, "limit": r + 0.03,
                         "rerun_dev_if_r_above": 0.10, "folder": rr["dir"].replace("\\", "/"),
                         "time": time.strftime("%Y-%m-%d %H:%M")}
    json.dump(cur, open(path, "w"), indent=1)
    print(json.dumps(cur[NAME[system]]))


def table_of(rows, sc, th_s, th_r, groups):
    keyed = {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v for k, v in sc.items()}
    return S.unit_table(rows, S.decide(keyed, th_s, th_r), groups)


def rechoose(system, key_path, split, workers=16, max_usd=1500.0, sample=None):
    """Amendment 13.2, only after a failed drift check of the same day: the rival's dev candidates re-asked in today's
    mode in fresh folders (data/p1v4/runs/api_rechoose/<time>/<system>/<setting>[_answers]/), the setting and
    thresholds re-chosen by the plan's rule (7.1, as choose()), and, in answers mode, the answer loss recomputed: the
    frozen probability-mode dev score minus the new answers score (five-part and must-listen, floored at 0), with
    its SE from the plan's three-way bootstrap (and the five-factor one). Writes final/<split>/api/override_<system>.json
    (never overwritten), which effective() hands to the final run, the decision table and the noise analysis.
    sample: dev rehearsal of this path only (operating points on a sample are not meaningful)."""
    import p1v4_test_report as TR
    if sample and split != "dev":
        raise SystemExit("--sample is for the dev rehearsal only")
    st = frozen(split)
    mode = modes_of(split)[NAME[system]]
    answers = mode == "answers"
    op = override_path(system, split)
    if os.path.exists(op):
        raise SystemExit(f"{op} exists: a re-choice is never overwritten")
    g = governing_check(system, split, mode)                # review M5: only after today's complete, failed check
    if g is None or g.get("pass") is not False:
        raise SystemExit(f"{NAME[system]}: today's governing drift check did not fail (or there is none); nothing to "
                         f"re-choose (amendment 13.2 supplement)")
    if sealed_split(split) and test_answers_exist(system, split, mode):
        raise SystemExit(f"{NAME[system]} already has answers on {split}: no re-choice after its first run on the "
                         f"split; the remaining runs wait for a day whose check passes (amendment 13.2 supplement)")
    last = [g]
    if answers:
        cands = [x["setting"] for x in json.load(open("results/main_v04/answer_only_dev.json"))[NAME[system]]["log"]]
    else:
        cands = [x["setting"] for x in json.load(open(os.path.join(OUT, system, f"{system}_dev.json")))["log"]]
    root = os.path.join("data/p1v4/runs/api_rechoose", time.strftime("%Y%m%d-%H%M%S"))
    rows_all = D.load_rows("dev")
    groups = S.load_groups("dev")
    keep = None
    if sample:
        keep = {(r["unit"], r["version"], k) for r, k in dev_points(sample, "dev")[1]}
    rows = [r for r in rows_all if keep is None or any((r["unit"], r["version"], p["k"]) in keep for p in r["points"])]
    ctx = C.Context("dev", asr="turbo")
    asked = [(f"{r['unit']}|{r['version']}|{p['k']}", a[0]) for r in rows for p in r["points"]
             if keep is None or (r["unit"], r["version"], p["k"]) in keep
             for a in ctx.situation(r, p["k"], "full")[1]]
    log, best, spent = [], None, 0.0
    for s in cands:
        rr = run(system, s, key_path, sample=sample, workers=workers, max_usd=max_usd - spent, answers=answers,
                 root=root)
        spent += rr["usd"]
        got = load_scores(os.path.join(rr["dir"], "responses.jsonl"))
        sc, missing = {}, 0
        for pid, q in asked:
            rec = got.get((pid, q))
            missing += rec is None
            val = 0.5 if rec is None else rec["score"] if not answers else \
                (1.0 if rec.get("answer") == "yes" else 0.0 if rec.get("answer") == "no" else 0.5)
            sc.setdefault(pid, {})[q] = val
        if missing > 0.005 * len(asked):
            log.append({"setting": s, "missing": missing, "skipped": True})
            continue
        res = S.operating_point(rows, {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v for k, v in sc.items()})
        path = os.path.join(root, system, f"scores_dev_{s}{'_answers' if answers else ''}.json")
        json.dump(sc, open(path, "w"))
        res.update(setting=s, missing=missing, path=path.replace("\\", "/"))
        log.append({k: res[k] for k in ("setting", "th_s", "th_r", "floors_met", "primary", "lowest_floor", "missing",
                                        "path")})
        rank = (res["floors_met"], res["primary"], res["lowest_floor"])
        if best is None or rank > best[0]:
            best = (rank, res)
        if spent >= max_usd:
            raise SystemExit(f"budget ${max_usd:.0f} reached during the re-choice")
    if best is None:
        raise SystemExit("no candidate complete enough to choose from")
    c = best[1]
    out = {"system": NAME[system], "mode": mode, "setting": c["setting"], "th_s": c["th_s"], "th_r": c["th_r"],
           "primary": c["primary"], "floors_met": c["floors_met"], "candidates": log, "root": root.replace("\\", "/"),
           "drift_check": last[-1], "sample": sample, "usd": spent, "time": time.strftime("%Y-%m-%d %H:%M:%S")}
    if answers:
        pe = st["api"][NAME[system]]["probabilities"]
        p_sc = json.load(open(os.path.join(OUT, system, f"scores_dev_{pe['setting']}.json")))
        n_sc = json.load(open(c["path"]))
        Tp = table_of(rows, {k: v for k, v in p_sc.items() if k in n_sc}, pe["th_s"], pe["th_r"], groups)
        Tn = table_of(rows, n_sc, c["th_s"], c["th_r"], groups)
        raw, se, se5 = {}, {}, {}
        for w, key in (("primary", "five_part"), ("audio", "must_listen")):
            i3 = S.interval(Tp, Tn, w)
            i5 = S.interval(Tp, Tn, w, factors=TR.FIVE)
            raw[key], se[key], se5[key] = 100 * i3["point"], 100 * i3["se"], 100 * i5["se"]
        out.update(answer_loss_points={k: max(0.0, v) for k, v in raw.items()}, answer_loss_points_raw=raw,
                   answer_loss_se_points=se, answer_loss_se_points_5f=se5,
                   probability_reference={"setting": pe["setting"], "th_s": pe["th_s"], "th_r": pe["th_r"]})
    json.dump(out, open(op, "w"), indent=1)
    print(json.dumps({k: v for k, v in out.items() if k != "candidates"}, indent=1))


def drift_compare(system):
    """Compare the drift re-asks with the stored dev answers at the frozen dev setting and thresholds."""
    info = json.load(open(os.path.join(OUT, system, f"{system}_dev.json")))
    setting = info["chosen"]
    e = next(x for x in info["log"] if x["setting"] == setting)
    th = {"S": e["th_s"], "R": e["th_r"]}
    new = load_scores(os.path.join(DRIFT, system, setting, "responses.jsonl"))
    old = load_scores(os.path.join(OUT, system, setting, "responses.jsonl"))
    keys = sorted(k for k in new if k in old)
    flips = sum((new[k]["score"] >= th[k[1]]) != (old[k]["score"] >= th[k[1]]) for k in keys)
    diffs = sorted(abs(new[k]["score"] - old[k]["score"]) for k in keys)
    rate = flips / max(1, len(keys))
    res = {"system": system, "setting": setting, "questions": len(keys), "flips": flips, "flip_rate": rate,
           "limit": DRIFT_LIMITS[system], "pass": rate <= DRIFT_LIMITS[system],
           "score_diff_median": diffs[len(diffs) // 2] if diffs else None, "score_diff_max": diffs[-1] if diffs else None,
           "model_versions": sorted({str(r.get("model_version")) for r in new.values()}),
           "time": time.strftime("%Y-%m-%d %H:%M")}
    json.dump(res, open(os.path.join(DRIFT, system, setting, "drift_check.json"), "w"), indent=1)
    print(json.dumps(res))


def cost(which=None):
    """which: None (the dev runs), "smoke" or "smoke_flex"."""
    tot = 0.0
    root = {None: OUT, "smoke": SMOKE, "smoke_flex": f"{SMOKE}_flex"}[which]
    for d in sorted(glob.glob(os.path.join(root, "*", "*", "responses.jsonl"))):
        recs = [json.loads(x) for x in open(d, encoding="utf-8")]
        ok = [r for r in recs if r["status"] == 200]
        usd = sum(r["usd"] for r in ok)
        tot += usd
        pt = sum(r["usage"].get("promptTokenCount", 0) for r in ok)
        ct = sum(r["usage"].get("cachedContentTokenCount", 0) for r in ok)
        th = sum(r["usage"].get("thoughtsTokenCount", 0) for r in ok)
        lat = sorted(r["latency_s"] for r in ok)
        print(f"{d}: {len(ok)} ok, {len(recs) - len(ok)} failed; prompt {pt / max(1, len(ok)):.0f} tok/call "
              f"(cached {ct / max(1, pt):.0%}), thinking {th / max(1, len(ok)):.0f} tok/call, "
              f"${usd:.3f} (${usd / max(1, len(ok)) * 1000:.2f} per 1,000 calls), "
              f"latency median {lat[len(lat) // 2] if lat else float('nan'):.1f} s")
    print(f"total ${tot:.2f}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd")
    ap.add_argument("args", nargs="*")
    ap.add_argument("--sample", type=int)
    ap.add_argument("--workers", type=int, default=16)
    ap.add_argument("--max-usd", type=float, default=None)       # run 200, final 2000, rechoose 1500 when not given
    ap.add_argument("--tier", choices=("standard", "flex"), default="standard")
    ap.add_argument("--split", default="dev")
    ap.add_argument("--drift", action="store_true")
    ap.add_argument("--answers", action="store_true")
    ap.add_argument("--final-folder", action="store_true")       # scores: read the final-run folder of the split
    a = ap.parse_args()
    if a.cmd == "run":
        run(*a.args[:3], sample=a.sample, workers=a.workers, max_usd=a.max_usd or 200.0, tier=a.tier, split=a.split,
            drift=a.drift, answers=a.answers)
    elif a.cmd == "probe":                         # final run, amendment 2.2 step 2: probe <key json> --split test
        probe(a.args[0], a.split)
    elif a.cmd == "final":                         # final <system> <key json> --split test [--sample N: dev only]
        final_run(a.args[0], a.args[1], a.split, workers=a.workers, max_usd=a.max_usd or 2000.0, sample=a.sample)
    elif a.cmd == "rechoose":                      # rechoose <system> <key json> --split test (amendment 13.2)
        rechoose(a.args[0], a.args[1], a.split, workers=a.workers, max_usd=a.max_usd or 1500.0, sample=a.sample)
    elif a.cmd == "switch":                        # switch <system> --split test (amendment 2.3)
        switch_to_answers(a.args[0], a.split)
    elif a.cmd == "drift-check":                   # drift-check <system> <key json> --split test (amendment 2.2 step 4)
        drift_check(a.args[0], a.args[1], a.split, workers=a.workers)
    elif a.cmd == "answer-drift":                  # answer-drift <system> <key json> (dev, before the freeze; 2.5)
        answer_drift_rate(a.args[0], a.args[1])
    elif a.cmd == "choose":
        choose(a.args[0])
    elif a.cmd == "scores":                        # scores <system> <setting> <split> [--answers] [--final-folder]
        split_scores(*a.args[:3], answers=a.answers, final=a.final_folder or sealed_split(a.args[2]))
    elif a.cmd == "drift-compare":
        drift_compare(a.args[0])
    elif a.cmd == "cost":
        cost(a.args[0] if a.args else None)
    else:
        raise SystemExit(__doc__)
